#!/usr/bin/env bash
# deploy_nav_logo.sh — Ust nav: ESKI altin nabiz ikonu + altin "Intelligence" -> GERCEK ucgen logo + mavi wordmark.
#   bi.js'i altin-nabiz imzasindan bulur (shells/bi.js veya root fark etmez), yamalar, dogrular, build + recreate.
set -e
cd /opt/krb-assessment
echo "" | base64 -d > /tmp/patch_nav_logo.py
# gercek servis edilen bi.js'i altin nabiz path'inden bul
BIJS=$(grep -rl 'd="M8 16h4l3-8 4 16 3-8h4"' --include='bi.js' . 2>/dev/null | head -1)
if [ -z "$BIJS" ]; then
  if grep -rlq 'NAV_LOGO_REAL_V1' --include='bi.js' . 2>/dev/null; then echo "zaten yamali (NAV_LOGO_REAL_V1)"; else echo "HATA: hedef bi.js bulunamadi"; exit 1; fi
else
  echo "hedef: $BIJS"
  cp "$BIJS" "$BIJS.bak.$(date +%s)"
  python3 /tmp/patch_nav_logo.py "$BIJS"
  grep -q 'NAV_LOGO_REAL_V1' "$BIJS" && echo "  ✓ ucgen logo + mavi wordmark yazildi" || { echo "HATA: yama yok"; exit 1; }
  grep -q 'stroke="#e2b04a"' "$BIJS" && { echo "HATA: altin nabiz hala var"; exit 1; } || echo "  ✓ altin nabiz gitti"
fi
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -20 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "BITTI. Ust nav artik gercek Derive Intelligence ucgen logosu + mavi wordmark."
